package com.biocircular.compostaje.dto;
import com.biocircular.compostaje.entity.TipoMovimiento; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
public final class Requests { private Requests(){} public record TipoResiduo(@NotBlank String codigo,@NotBlank String nombre,@Size(max=250) String descripcion){} public record IngresoResiduo(UUID recoleccionExternaId,@NotNull UUID tipoResiduoId,@NotNull UUID responsableId,OffsetDateTime fechaHora,@NotNull @DecimalMin("0.01") BigDecimal pesoKg,String observacion){} public record Lote(@NotNull UUID responsableId,LocalDate fechaInicio){} public record Etapa(@NotNull UUID etapaId,@NotNull UUID responsableId){} public record Observacion(@NotNull UUID loteEtapaId,@NotNull UUID responsableId,@NotBlank String nota){} public record Produccion(@NotNull UUID loteId,@NotNull @DecimalMin("0.01") BigDecimal cantidadKg,LocalDate fechaProduccion,boolean aptoEntrega){} public record Movimiento(@NotNull UUID compostId,@NotNull TipoMovimiento tipo,@NotNull @DecimalMin("0.01") BigDecimal cantidadKg,@NotBlank String motivo,@NotNull UUID usuarioId){} }
